// First-launch setup — PAT instructions on the left, paste field +
// live validation on the right.
//
// Behaviour:
//   - Mandatory first-launch screen per CONTEXT.md (no Skip button —
//     the app has nothing to show without auth).
//   - Validation states: idle / validating / validated / error.
//   - Validating hits GitHub's /user endpoint; success persists the
//     token to localStorage (ADR 0007 web-build policy) and the
//     parent advances to the Inbox.
//   - Error renders GitHub's actual message + the failing endpoint
//     so the user knows *why* (401 bad creds vs 403 SSO vs network).
//
// All visible UI is shadcn primitives + Tailwind utility classes
// (ADR 0011). Static layout uses utility classes; no inline style
// props remain — none of the values here are runtime-derived.

import { useState, type ReactNode } from 'react';
import { useNavigate } from '@tanstack/react-router';
import { INBOX_DEFAULTS } from '../router/search';
import {
  Check,
  CheckCircle2,
  ChevronRight,
  ExternalLink as ExternalLinkIcon,
  Info,
  Loader2,
  XCircle,
} from 'lucide-react';
import { setToken } from '../auth/tokenStore';
import { getViewer, GitHubError } from '../github/client';
import type { Viewer } from '../github/types';
import { PyorWindow } from '../ui/PyorWindow';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

type SetupState = 'idle' | 'validating' | 'validated' | 'error';

interface Props {
  onContinue?: () => void;
  fluid?: boolean;
  width?: number;
  height?: number;
}

const REQUIRED_SCOPES = ['repo', 'notifications', 'read:org', 'read:user'];

export function SetupScreen({
  onContinue: onContinueProp,
  fluid = false,
  width = 920,
  height = 660,
}: Props) {
  const navigate = useNavigate();
  // After a token validates, enter the app. Defaults to the router
  // (→ Inbox); the prop override is kept for tests/stories.
  const onContinue =
    onContinueProp ??
    (() => void navigate({ to: '/inbox', search: INBOX_DEFAULTS }));
  const [tokenInput, setTokenInput] = useState('');
  const [state, setState] = useState<SetupState>('idle');
  const [viewer, setViewer] = useState<Viewer | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [errorStatus, setErrorStatus] = useState<number | null>(null);

  const validate = async () => {
    const candidate = tokenInput.trim();
    if (!candidate) {
      setState('error');
      setErrorMsg('Paste your token first.');
      setErrorStatus(null);
      return;
    }
    setState('validating');
    setErrorMsg('');
    setErrorStatus(null);
    try {
      const v = await getViewer(candidate);
      // Soft scope check — surface a warning if scopes are missing but
      // don't block, in case GitHub adds a new scope name later.
      const missing = REQUIRED_SCOPES.filter((s) => !v.scopes.includes(s));
      if (missing.length > 0) {
        setState('error');
        setErrorMsg(
          `Token is valid for user ${v.login}, but missing required scopes: ${missing.join(', ')}. Regenerate with the four scopes listed below.`,
        );
        setErrorStatus(200);
        return;
      }
      setViewer(v);
      setToken(candidate);
      setState('validated');
    } catch (e) {
      setState('error');
      if (e instanceof GitHubError) {
        setErrorMsg(e.message);
        setErrorStatus(e.status);
      } else {
        setErrorMsg(String(e));
        setErrorStatus(null);
      }
    }
  };

  const reset = () => {
    setState('idle');
    setErrorMsg('');
    setErrorStatus(null);
    setViewer(null);
  };

  return (
    <PyorWindow
      width={width}
      height={height}
      title="Pyor"
      subtitle="Set up GitHub access"
      fluid={fluid}
      hideStatusBar
      flushLeft
    >
      <div className="flex flex-1 min-h-0">
        {/* LEFT — instructions */}
        <div className="w-[460px] overflow-auto border-r bg-panel px-8 py-7">
          <SectionLabel>Step 1 of 1 · Connect GitHub</SectionLabel>
          <h1 className="m-0 font-display text-2xl font-bold leading-tight tracking-tight text-foreground">
            Paste a Personal Access&nbsp;Token
          </h1>
          <p className="mt-2 mb-[18px] text-[13px] leading-normal text-muted-foreground">
            Pyor reads PRs directly from GitHub using your account. The token
            stays in your macOS Keychain. We don't run a server.
          </p>

          <Step
            n="1"
            label="Open GitHub → Settings → Developer settings → Personal access tokens (classic)"
          >
            <ExternalLinkPill>github.com/settings/tokens</ExternalLinkPill>
          </Step>

          <Step
            n="2"
            label="Click 'Generate new token (classic)'. Give it a name like “Pyor”."
          >
            <MockScreenshot />
          </Step>

          <Step
            n="3"
            label="Tick exactly these four scopes — no more, no less."
          >
            <ScopeList />
          </Step>

          <Step n="4" label="Copy the token. GitHub shows it once." last>
            <div className="flex items-start gap-2 rounded-md border border-pyor-warn/40 bg-pyor-warn/10 px-2.5 py-2 text-[12px] text-pyor-warn">
              <Info className="size-3.5 shrink-0 mt-0.5" />
              <span className="text-foreground">
                <b>SSO orgs:</b> after creating the token, click "Configure SSO"
                next to it and authorize the orgs you review for. No admin
                approval needed.
              </span>
            </div>
          </Step>
        </div>

        {/* RIGHT — paste & validate */}
        <div className="flex flex-1 flex-col min-w-0 px-9 py-7">
          <SectionLabel>Token</SectionLabel>

          <Input
            value={tokenInput}
            onChange={(e) => {
              setTokenInput(e.target.value);
              if (state === 'error') reset();
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && state !== 'validating') validate();
            }}
            type="password"
            autoComplete="off"
            spellCheck={false}
            placeholder="ghp_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
            disabled={state === 'validated'}
          />

          {state === 'validated' && viewer && (
            <div className="mt-3.5 rounded-lg border border-pyor-pass/40 bg-pyor-pass/10 px-4 py-3.5">
              <div className="mb-2.5 flex items-center gap-2">
                <CheckCircle2 className="size-[15px] text-pyor-pass" />
                <span className="text-[13px] font-semibold">
                  Connected as {viewer.login}
                </span>
              </div>
              <div className="grid grid-cols-[110px_1fr] gap-y-1.5 text-[12px]">
                <span className="text-muted-foreground">Account</span>
                <span>{viewer.name}</span>
                <span className="text-muted-foreground">Scopes</span>
                <span className="font-mono text-[11.5px]">
                  {viewer.scopes.join(', ')}
                </span>
                <span className="text-muted-foreground">Rate limit</span>
                <span className="tabular-nums">
                  {viewer.rate.remaining.toLocaleString()} /{' '}
                  {viewer.rate.limit.toLocaleString()} · resets{' '}
                  {formatResetIn(viewer.rate.resetAt)}
                </span>
              </div>
            </div>
          )}

          {state === 'error' && (
            <div className="mt-3.5 rounded-lg border border-destructive/40 bg-destructive/10 px-4 py-3.5">
              <div className="mb-1.5 flex items-center gap-2">
                <XCircle className="size-[15px] text-destructive" />
                <span className="text-[13px] font-semibold">
                  {errorStatus === 401
                    ? 'Token rejected'
                    : errorStatus === 403
                      ? 'Token forbidden (SSO or rate limit)'
                      : errorStatus === 200
                        ? 'Token valid but missing scopes'
                        : 'Validation failed'}
                </span>
              </div>
              <div className="text-[12px] leading-normal text-muted-foreground">
                {errorStatus !== null && errorStatus !== 200 && (
                  <>
                    GitHub returned{' '}
                    <code className="font-mono text-[11px]">
                      {errorStatus} {errorMsg.slice(0, 60)}
                    </code>
                    .{' '}
                  </>
                )}
                {(errorStatus === null || errorStatus === 200) && (
                  <span>{errorMsg}</span>
                )}
                {errorStatus === 401 && (
                  <>
                    Check it begins with{' '}
                    <code className="font-mono text-[11px]">ghp_</code> and was
                    copied in full.
                  </>
                )}
              </div>
            </div>
          )}

          <div className="mt-[22px]">
            <SectionLabel>Why these scopes</SectionLabel>
            <ScopeReason
              scope="repo"
              reason="Read PR diffs, threads, viewed-state. Required for private repos."
            />
            <ScopeReason
              scope="notifications"
              reason="Detect new activity without polling every PR individually."
            />
            <ScopeReason
              scope="read:org"
              reason="Resolve team review requests into PRs in your Inbox."
            />
            <ScopeReason
              scope="read:user"
              reason="Show your own avatar & identify the “@me” in queries."
            />
          </div>

          <div className="flex-1" />

          <div className="mt-[18px] flex items-center gap-2.5 border-t pt-[18px]">
            <span className="flex-1 text-[12px] text-muted-foreground/80">
              Stored in <span className="text-muted-foreground">Keychain</span>{' '}
              under{' '}
              <code className="font-mono text-[11px]">com.pyor.app</code>
            </span>
            <Button
              size="default"
              disabled={state === 'validating'}
              onClick={
                state === 'validated'
                  ? onContinue
                  : state === 'validating'
                    ? undefined
                    : validate
              }
            >
              {state === 'validating' && <Loader2 className="animate-spin" />}
              {state === 'validated' && <Check />}
              {state === 'validating'
                ? 'Validating…'
                : state === 'validated'
                  ? 'Open Inbox'
                  : 'Validate'}
              {state === 'validated' && <ChevronRight />}
            </Button>
          </div>
        </div>
      </div>
    </PyorWindow>
  );
}

function formatResetIn(resetAt: Date): string {
  const ms = resetAt.getTime() - Date.now();
  if (ms < 0) return 'now';
  const m = Math.round(ms / 60_000);
  if (m < 60) return `in ${m}m`;
  const h = Math.floor(m / 60);
  const rem = m % 60;
  return `in ${h}h ${rem}m`;
}

function SectionLabel({ children }: { children: ReactNode }) {
  return (
    <div className="mb-2.5 text-[11px] font-semibold uppercase tracking-[0.6px] text-muted-foreground/80">
      {children}
    </div>
  );
}

// Numbered step rail. The vertical connector between steps is rendered
// inline (not the last step) so the rail visually links the four
// instructions without a wrapping container that would also pad them.
function Step({
  n,
  label,
  children,
  last,
}: {
  n: string;
  label: string;
  children?: ReactNode;
  last?: boolean;
}) {
  return (
    <div className={`relative flex gap-3 ${last ? 'pb-0' : 'pb-4'}`}>
      <div className="flex shrink-0 flex-col items-center">
        <div className="flex size-[22px] items-center justify-center rounded-full border border-border bg-card text-[11px] font-semibold text-muted-foreground">
          {n}
        </div>
        {!last && <div className="mt-1 w-px flex-1 bg-border" />}
      </div>
      <div className="flex-1 pt-px pb-1">
        <div
          className={`text-[13px] leading-snug text-foreground ${children ? 'mb-2' : ''}`}
        >
          {label}
        </div>
        {children}
      </div>
    </div>
  );
}

function ExternalLinkPill({ children }: { children: ReactNode }) {
  return (
    <span className="inline-flex cursor-pointer items-center gap-1.5 rounded-md border bg-card px-2 py-1 font-mono text-[11.5px] text-pyor-link">
      {children}
      <ExternalLinkIcon className="size-3" />
    </span>
  );
}

// Decorative mock of GitHub's token-creation page. Pure layout, no
// interaction — exists to anchor step 2 visually.
function MockScreenshot() {
  return (
    <div className="flex h-24 w-full flex-col overflow-hidden rounded-md border bg-card">
      <div className="flex h-[18px] items-center gap-1.5 border-b bg-muted px-2">
        <div className="size-1.5 rounded-sm bg-border" />
        <div className="font-mono text-[9px] text-muted-foreground/80">
          github.com/settings/tokens/new
        </div>
      </div>
      <div className="flex flex-1 flex-col gap-1.5 px-2.5 py-2">
        <div className="h-2 w-2/5 rounded-sm bg-border/60" />
        <div className="flex h-[22px] items-center rounded-sm border bg-card px-1.5 font-mono text-[9px] text-muted-foreground/80">
          Pyor
        </div>
        <div className="mt-1 flex h-4 w-[86px] items-center justify-center rounded-sm bg-pyor-pass text-[9px] font-semibold text-white">
          Generate token
        </div>
      </div>
    </div>
  );
}

interface Scope {
  name: string;
  sub: string;
  on: boolean;
  required?: boolean;
}

function ScopeList() {
  const scopes: Scope[] = [
    {
      name: 'repo',
      sub: 'Full control of private repositories',
      on: true,
      required: true,
    },
    {
      name: 'notifications',
      sub: 'Access notifications',
      on: true,
      required: true,
    },
    {
      name: 'read:org',
      sub: 'Read org & team membership',
      on: true,
      required: true,
    },
    {
      name: 'read:user',
      sub: 'Read user profile data',
      on: true,
      required: true,
    },
    {
      name: 'workflow',
      sub: 'Update GitHub Action workflows',
      on: false,
    },
  ];
  return (
    <div className="overflow-hidden rounded-md border bg-card">
      {scopes.map((s, i) => (
        <div
          key={s.name}
          className={`flex items-start gap-2.5 px-2.5 py-[7px] ${
            i ? 'border-t' : ''
          } ${s.required ? 'bg-pyor-pass/10' : ''}`}
        >
          <div
            className={`mt-px flex size-3.5 shrink-0 items-center justify-center rounded-sm border ${
              s.on
                ? 'border-pyor-pass bg-pyor-pass'
                : 'border-border bg-card'
            }`}
          >
            {s.on && <Check className="size-2.5 text-white" />}
          </div>
          <div className="min-w-0 flex-1">
            <div className="font-mono text-[11.5px] font-medium text-foreground">
              {s.name}
            </div>
            <div className="text-[11px] text-muted-foreground">{s.sub}</div>
          </div>
          {s.required && (
            <Badge
              variant="outline"
              className="mt-0.5 border-pyor-pass/40 px-1.5 py-0 text-[10px] font-semibold text-pyor-pass"
            >
              REQUIRED
            </Badge>
          )}
        </div>
      ))}
    </div>
  );
}

function ScopeReason({ scope, reason }: { scope: string; reason: string }) {
  return (
    <div className="flex items-start gap-2.5 py-1.5">
      <span className="mt-px shrink-0 rounded-sm bg-muted px-1.5 py-0.5 font-mono text-[11px] font-semibold text-foreground">
        {scope}
      </span>
      <span className="text-[12px] leading-snug text-muted-foreground">
        {reason}
      </span>
    </div>
  );
}
